use super::retransmission_requestor::RetransmitRequest; use std::time::{Duration, Instant}; pub struct MissingRange { pub offset: u64, pub length: u64, pub timer: Instant } pub struct ReorderBuffer { pub stream_id: u64, pub missing_ranges: Vec<MissingRange>, pub max_size: u64 } impl ReorderBuffer { pub fn new(stream_id: u64) -> Self { Self { stream_id, missing_ranges: Vec::new(), max_size: 256 * 1024 } } pub fn add_missing_range(&mut self, offset: u64, length: u64) { self.missing_ranges.push(MissingRange { offset, length, timer: Instant::now() }); } pub fn check_timers(&mut self) -> Vec<RetransmitRequest> { let now = Instant::now(); let mut requests = Vec::new(); self.missing_ranges.retain(|range| { if now.duration_since(range.timer) >= Duration::from_millis(100) { requests.push(RetransmitRequest { stream_id: self.stream_id, offset: range.offset, length: range.length }); false } else { true } }); requests } }
